// Read-only Hyperliquid query. Manual executions are preview-only.
const config = $input.first().json;
const wallet = String(config.walletAddress || '').trim().toLowerCase();
if (!/^0x[0-9a-f]{40}$/.test(wallet) || /^0x0{40}$/.test(wallet)) {
  throw new Error('Set walletAddress to a non-zero public master-account or subaccount address. Never enter a private key.');
}
const preview = $execution.mode === 'manual';
const chatId = String(config.telegramChatId || '').trim();
if (!preview && !/^(?:-?\d+|@[A-Za-z][A-Za-z0-9_]{4,})$/.test(chatId)) {
  throw new Error('Set telegramChatId and select Telegram credentials before enabling scheduled runs.');
}
const store = $getWorkflowStaticData('global');
const previous = store.hlWalletMonitor;
if (previous && (previous.version !== 1 || !Number.isSafeInteger(previous.endTime) || !Number.isSafeInteger(previous.baselineAt) || !Array.isArray(previous.seen))) {
  throw new Error('Invalid stored checkpoint. Inspect the saved state instead of silently resetting the monitor.');
}
const state = !preview && previous?.wallet === wallet ? previous : null;
const endTime = Date.now() - 10_000; // Brief indexing delay; overlap below catches some late records.
const overlapMs = 120_000;
if (state && state.endTime >= endTime) throw new Error('Non-increasing checkpoint time. Check clock/overlapping runs.');
if (state && endTime - state.endTime > 86_400_000) {
  throw new Error('Monitor inactive for over 24h. Historical coverage cannot be guaranteed. Reconcile the gap before creating a fresh baseline.');
}
const startTime = state ? Math.max(state.baselineAt, state.endTime - overlapMs) : endTime - (preview ? 900_000 : 300_000);
return [{json: {
  wallet, label: String(config.walletLabel || 'Watched wallet').slice(0, 40), chatId,
  preview, initial: !state, endTime, overlapMs,
  baselineAt: state ? state.baselineAt : endTime,
  previousEndTime: state ? state.endTime : null,
  seen: state ? state.seen : [],
  request: {type: 'userFillsByTime', user: wallet, startTime, endTime, aggregateByTime: false},
}}];

const ctx = $('Prepare request').first().json;
const response = $input.first().json;
if (response.statusCode !== 200 || !Array.isArray(response.body)) {
  throw new Error('Hyperliquid did not return a successful fill array; checkpoint unchanged.');
}
// Conservative guard: docs specify 2,000 fills, and a generic 500 element/block page limit.
// This small-wallet template has no pagination. Reject >=500 rather than assume completeness.
if (response.body.length >= 500) {
  throw new Error('500+ fills returned: possible pagination/retention gap. This template is for lower-volume wallets; checkpoint unchanged.');
}
const decimal = /^-?\d+(?:\.\d+)?$/;
function validDecimal(value, positive = false) {
  return typeof value === 'string' && value.length <= 50 && decimal.test(value) && Number.isFinite(Number(value)) && (!positive || Number(value) > 0);
}
function identity(fill) {
  if (!(typeof fill.tid === 'string' && /^\d+$/.test(fill.tid)) && !(Number.isSafeInteger(fill.tid) && fill.tid >= 0)) {
    throw new Error('Missing or unsafe trade ID; cannot deduplicate reliably.');
  }
  return `${fill.coin}:${String(fill.tid)}`;
}
function units(value, scale) {
  const negative = value.startsWith('-');
  const [whole, part = ''] = value.replace(/^-/, '').split('.');
  return BigInt(whole + part.padEnd(scale, '0')) * (negative ? -1n : 1n);
}
function action(fill) {
  if (fill.coin.startsWith('@') || fill.coin.includes('/')) return fill.side === 'B' ? 'Spot buy' : 'Spot sell';
  if (!validDecimal(fill.startPosition)) return `${fill.side === 'B' ? 'Buy' : 'Sell'} fill (position change unknown)`;
  const scale = Math.max((fill.startPosition.split('.')[1] || '').length, (fill.sz.split('.')[1] || '').length);
  const before = units(fill.startPosition, scale);
  const delta = units(fill.sz, scale) * (fill.side === 'B' ? 1n : -1n);
  const after = before + delta;
  if (before === 0n) return after > 0n ? 'Open long' : 'Open short';
  if (after === 0n) return before > 0n ? 'Close long' : 'Close short';
  if (before > 0n && after < 0n) return 'Reverse long to short';
  if (before < 0n && after > 0n) return 'Reverse short to long';
  const added = before > 0n ? delta > 0n : delta < 0n;
  return `${added ? 'Increase' : 'Reduce'} ${before > 0n ? 'long' : 'short'}`;
}
function esc(value) {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function compactNumber(value) {
  const n = Number(value);
  return Math.abs(n) >= 1e12 || (n !== 0 && Math.abs(n) < 1e-8) ? n.toExponential(6) : n.toLocaleString('en-US', {maximumFractionDigits: 8});
}
const unique = new Map();
for (const fill of response.body) {
  if (!fill || typeof fill.coin !== 'string' || !fill.coin || fill.coin.length > 60 || !['A', 'B'].includes(fill.side) || !validDecimal(fill.px, true) || !validDecimal(fill.sz, true) || !Number.isSafeInteger(fill.time) || fill.time < ctx.request.startTime || fill.time > ctx.endTime) {
    throw new Error('Malformed or out-of-window fill; checkpoint unchanged.');
  }
  const key = identity(fill);
  const old = unique.get(key);
  if (old && ['px', 'sz', 'time', 'side', 'startPosition'].some(field => old[field] !== fill[field])) throw new Error('Conflicting records for a trade ID.');
  unique.set(key, {...fill, key});
}
const ordered = [...unique.values()].sort((a, b) => a.time - b.time || a.key.localeCompare(b.key));
const known = new Set(ctx.seen.map(row => row.key));
const fresh = ordered.filter(fill => !known.has(fill.key) && (ctx.preview || fill.time > ctx.baselineAt));
const recent = new Map(ctx.seen.filter(row => row.time >= ctx.endTime - ctx.overlapMs).map(row => [row.key, row]));
for (const fill of ordered) if (fill.time >= ctx.endTime - ctx.overlapMs) recent.set(fill.key, {key: fill.key, time: fill.time});
const checkpoint = {version: 1, wallet: ctx.wallet, baselineAt: ctx.baselineAt, endTime: ctx.endTime, seen: [...recent.values()]};
const trackerUrl = `https://marketdepthlab.com/tools/hyperliquid-wallet-tracker/#address=${ctx.wallet}`;
const display = fresh.slice(-6);
const lines = [
  `<b>Hyperliquid wallet fills${ctx.preview ? ' — PREVIEW' : ''}</b>`,
  esc(ctx.label), `<code>${ctx.wallet}</code>`,
  `${fresh.length} ${ctx.preview ? 'recent' : 'newly observed'} fill(s); times in UTC`, '',
];
for (const fill of display) {
  const fee = validDecimal(fill.fee) && typeof fill.feeToken === 'string'
    ? ` | Fee ${esc(compactNumber(fill.fee))} ${esc(fill.feeToken.slice(0, 15))}` : '';
  lines.push(`<b>${esc(fill.coin)} · ${esc(action(fill))}</b>`);
  lines.push(`${esc(compactNumber(fill.sz))} @ ${esc(compactNumber(fill.px))}${fee}`);
  lines.push(new Date(fill.time).toISOString().replace('T', ' ').replace('.000Z', 'Z'), '');
}
if (fresh.length > display.length) lines.push(`Showing the latest ${display.length} of ${fresh.length} fills in this batch.`, '');
lines.push(`<a href="${trackerUrl}">Inspect this wallet on Market Depth Lab</a>`);
lines.push('Fill activity only; not a complete portfolio or deposit/withdrawal monitor.');
const message = lines.join('\n');
if (message.length > 4000) throw new Error('Message exceeds safe Telegram length; checkpoint unchanged.');
const baselineOnly = ctx.initial && !ctx.preview;
return [{json: {
  status: ctx.preview ? 'preview_only' : baselineOnly ? 'baseline_created_no_alert' : fresh.length ? 'new_fills' : 'no_new_fills',
  preview: ctx.preview, send: !ctx.preview && !baselineOnly && fresh.length > 0,
  chatId: ctx.chatId, wallet: ctx.wallet, previousEndTime: ctx.previousEndTime,
  count: fresh.length, displayedCount: display.length, message, trackerUrl,
  checkpoint, actions: display.map(fill => ({id: fill.key, action: action(fill), coin: fill.coin})),
}}];

const batch = $('Build alert').first().json;
if (batch.preview) return [{json: {status: 'preview_only', message: batch.message, count: batch.count, stateSaved: false}}];
// The send branch reaches this node only after a successful Telegram response.
if (batch.send) {
  const delivery = $input.first().json;
  const result = delivery.result || delivery;
  if (!Number.isSafeInteger(result.message_id)) throw new Error('Telegram delivery not confirmed; checkpoint unchanged.');
}
const store = $getWorkflowStaticData('global');
const current = store.hlWalletMonitor;
if (current?.wallet === batch.wallet && current.endTime !== batch.previousEndTime) {
  throw new Error('Concurrent checkpoint change detected. Run one execution at a time.');
}
store.hlWalletMonitor = batch.checkpoint;
return [{json: {status: batch.status, count: batch.count, checkpointTime: new Date(batch.checkpoint.endTime).toISOString(), stateSavedOnSuccessfulExecution: true}}];
